import 'package:flutter/material.dart';
import '../creart_store.dart';
import 'detail_postingan_page.dart';

class KategoriPage extends StatefulWidget { const KategoriPage({super.key}); @override State<KategoriPage> createState()=>_KategoriPageState(); }
class _KategoriPageState extends State<KategoriPage>{
 final store=CreArtStore.instance; String selected='Ilustrasi'; String query='';
 final categories=[('Ilustrasi','Sketsa, karakter, dan cerita visual',Icons.draw_outlined),('Fotografi','Momen dari sudut pandang',Icons.camera_alt_outlined),('Desain','Bentuk, tata letak, dan identitas',Icons.auto_awesome_outlined),('Digital Art','Eksperimen seni digital',Icons.palette_outlined),('Lainnya','Tulisan dan bentuk kreatif lainnya',Icons.more_horiz)];
 @override Widget build(BuildContext context)=>AnimatedBuilder(animation:store,builder:(context,_){
 final filtered=store.artworks.where((a)=>(selected=='Semua'||a.category.toLowerCase()==selected.toLowerCase())&&(query.isEmpty||a.title.toLowerCase().contains(query)||a.creator.toLowerCase().contains(query)||a.category.toLowerCase().contains(query))).toList();
 return Scaffold(appBar:AppBar(title:const Text('Jelajahi kategori',style:TextStyle(fontWeight:FontWeight.bold)),),body:ListView(padding:const EdgeInsets.all(20),children:[
 const Text('Ikuti rasa ingin tahumu.',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const Text('Temukan karya dari beragam sudut seni.',style:TextStyle(color:Colors.grey)),const SizedBox(height:18),
 TextField(onChanged:(v)=>setState(()=>query=v.trim().toLowerCase()),decoration:InputDecoration(hintText:'Cari kategori, karya, atau kreator',prefixIcon:const Icon(Icons.search),suffixIcon:query.isNotEmpty?IconButton(icon:const Icon(Icons.clear),onPressed:()=>setState(()=>query='')):null)),
 const SizedBox(height:16),
 Wrap(spacing:8,runSpacing:8,children:[ChoiceChip(label:const Text('Semua'),selected:selected=='Semua',onSelected:(_)=>setState(()=>selected='Semua')), ...categories.map((c)=>ChoiceChip(label:Text(c.$1),selected:selected==c.$1,onSelected:(_)=>setState(()=>selected=c.$1)))]),
 const SizedBox(height:20),
 ...categories.where((c)=>query.isEmpty||c.$1.toLowerCase().contains(query)||c.$2.toLowerCase().contains(query)).map((c)=>_categoryTile(c.$1,c.$2,c.$3)),
 const SizedBox(height:16),Row(children:[Expanded(child:Text(selected=='Semua'?'Semua karya':'Karya $selected',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18))),Text('${filtered.length} karya',style:const TextStyle(color:Colors.grey))]),const SizedBox(height:12),
 if(filtered.isEmpty)const Padding(padding:EdgeInsets.all(28),child:Text('Tidak ada karya yang cocok dengan pencarian.',textAlign:TextAlign.center))
 else GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),itemCount:filtered.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:.72),itemBuilder:(context,i){final art=filtered[i];return InkWell(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>DetailPostinganPage(artwork:art))),child:Container(decoration:BoxDecoration(color:Colors.white,border:Border.all(color:const Color(0xFFE9E3F0)),borderRadius:BorderRadius.circular(14)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Container(width:double.infinity,decoration:BoxDecoration(gradient:LinearGradient(colors:[art.color1,art.color2]),borderRadius:const BorderRadius.vertical(top:Radius.circular(14))),child:const Icon(Icons.palette_outlined,size:40,color:Color(0xFF7052C8)))),Padding(padding:const EdgeInsets.all(10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(art.title,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.bold)),Text(art.creator,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:12,color:Colors.grey)),Row(children:[Text(art.category,style:const TextStyle(fontSize:11,color:Color(0xFF7052C8))),const Spacer(),Icon(art.isSaved?Icons.bookmark:Icons.bookmark_border,size:18,color:const Color(0xFF7052C8))])]))])));}),
 ]));});
 Widget _categoryTile(String title,String subtitle,IconData icon){final isSelected=selected==title;return Container(margin:const EdgeInsets.only(bottom:8),decoration:BoxDecoration(color:isSelected?const Color(0xFFF5F0FC):Colors.white,border:Border.all(color:isSelected?const Color(0x5C7052C8):const Color(0xFFE9E3F0)),borderRadius:BorderRadius.circular(12)),child:ListTile(leading:CircleAvatar(backgroundColor:const Color(0xFFE9DDFB),child:Icon(icon,color:const Color(0xFF7052C8))),title:Text(title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(subtitle,style:const TextStyle(fontSize:12)),trailing:Icon(isSelected?Icons.check_circle:Icons.chevron_right,color:const Color(0xFF7052C8)),onTap:()=>setState(()=>selected=title)));}
}
